ValidationRule.errorConditionFormula:
AND( 
    RecordType.Name ='Agent Acquisition', 
    OR(
       (AND(
            ISPICKVAL( LeadSource , "Website"), 
            ISBLANK(TEXT(Where_did_you_hear_about_us__c))
            )),
       (AND( 
           TEXT(LeadSource) !=  "Website", 
           NOT(ISBLANK(TEXT(Where_did_you_hear_about_us__c)))
         ))
      )
)
